#!/usr/bin/env python3
"""A small persistent JSON key-value HTTP service (Python 3.11+)."""

from __future__ import annotations

import argparse
import json
import math
import os
import signal
import sys
import tempfile
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import unquote_to_bytes, urlsplit


MAX_BODY = 1024 * 1024


class KVStore:
    def __init__(self, data_path: str) -> None:
        self.path = Path(data_path)
        self.lock = threading.RLock()
        self.entries: dict[str, dict[str, object]] = {}
        self._load()

    def _load(self) -> None:
        with self.lock:
            try:
                with self.path.open("r", encoding="utf-8") as file:
                    raw = json.load(file)
                if not isinstance(raw, dict):
                    raise ValueError("top-level JSON must be an object")
                entries = raw.get("entries", raw)
                if not isinstance(entries, dict):
                    raise ValueError("entries must be an object")
                for key, entry in entries.items():
                    if (isinstance(key, str) and isinstance(entry, dict)
                            and "value" in entry):
                        expires = entry.get("expires_at")
                        if expires is None or (isinstance(expires, (int, float))
                                              and not isinstance(expires, bool)
                                              and math.isfinite(expires)
                                              and expires > time.time()):
                            self.entries[key] = {"value": entry["value"], "expires_at": expires}
                self._purge_locked(persist=False)
            except FileNotFoundError:
                return
            except (OSError, ValueError, json.JSONDecodeError) as exc:
                print(f"warning: unable to load {self.path}: {exc}", file=sys.stderr, flush=True)

    def _purge_locked(self, persist: bool = True) -> bool:
        now = time.time()
        expired = [key for key, entry in self.entries.items()
                   if entry["expires_at"] is not None and entry["expires_at"] <= now]
        for key in expired:
            del self.entries[key]
        if expired and persist:
            self._persist_locked()
        return bool(expired)

    def _persist_locked(self) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        payload = json.dumps({"entries": self.entries}, ensure_ascii=False,
                             allow_nan=False, separators=(",", ":"))
        fd, temporary = tempfile.mkstemp(prefix=f".{self.path.name}.", dir=self.path.parent,
                                         text=True)
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as file:
                file.write(payload)
                file.flush()
                os.fsync(file.fileno())
            os.replace(temporary, self.path)
        except Exception:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass
            raise

    def put(self, key: str, value: object, ttl: float | None) -> bool:
        with self.lock:
            self._purge_locked()
            existed = key in self.entries
            self.entries[key] = {"value": value,
                                 "expires_at": None if ttl is None else time.time() + ttl}
            self._persist_locked()
            return existed

    def get(self, key: str) -> object | None:
        with self.lock:
            self._purge_locked()
            entry = self.entries.get(key)
            return None if entry is None else entry["value"]

    def delete(self, key: str) -> bool:
        with self.lock:
            self._purge_locked()
            if key not in self.entries:
                return False
            del self.entries[key]
            self._persist_locked()
            return True

    def keys(self) -> list[str]:
        with self.lock:
            self._purge_locked()
            return sorted(self.entries)


class Handler(BaseHTTPRequestHandler):
    store: KVStore
    protocol_version = "HTTP/1.1"

    def log_message(self, format: str, *args: object) -> None:
        print(f"{self.address_string()} - {format % args}", file=sys.stderr, flush=True)

    def _respond(self, status: int, body: object | None = None) -> None:
        encoded = b"" if body is None else json.dumps(body, ensure_ascii=False,
                                                        allow_nan=False).encode("utf-8")
        self.send_response(status)
        if body is not None:
            self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(encoded)))
        self.end_headers()
        if encoded:
            self.wfile.write(encoded)

    def _error(self, status: int, message: str) -> None:
        self._respond(status, {"error": message})

    def _key(self) -> str | None:
        path = urlsplit(self.path).path
        prefix = "/v1/kv/"
        if not path.startswith(prefix):
            return None
        encoded = path[len(prefix):]
        if not encoded or "/" in encoded:
            return None
        try:
            key = unquote_to_bytes(encoded).decode("utf-8")
        except UnicodeDecodeError:
            return None
        return key if key and "/" not in key else None

    def _body(self) -> object | None:
        length = self.headers.get("Content-Length")
        if length is None:
            self._error(400, "Content-Length is required")
            return None
        try:
            count = int(length)
        except ValueError:
            self._error(400, "invalid Content-Length")
            return None
        if count < 0 or count > MAX_BODY:
            self._error(413, "request body too large")
            return None
        try:
            return json.loads(self.rfile.read(count).decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            self._error(400, "malformed JSON")
            return None

    def do_GET(self) -> None:
        path = urlsplit(self.path).path
        if path == "/health":
            self._respond(200, {"status": "ok"})
        elif path == "/v1/keys":
            self._respond(200, {"keys": self.store.keys()})
        elif (key := self._key()) is not None:
            value = self.store.get(key)
            if value is None and key not in self.store.keys():
                self._error(404, "key not found")
            else:
                self._respond(200, {"key": key, "value": value})
        else:
            self._error(404, "unknown route")

    def do_PUT(self) -> None:
        key = self._key()
        if key is None:
            self._error(404, "unknown route")
            return
        body = self._body()
        if not isinstance(body, dict) or "value" not in body or set(body) - {"value", "ttl_seconds"}:
            self._error(400, "body must be an object containing value")
            return
        ttl = body.get("ttl_seconds")
        if ttl is not None and (isinstance(ttl, bool) or not isinstance(ttl, (int, float))
                                or not math.isfinite(ttl) or ttl <= 0):
            self._error(400, "ttl_seconds must be a finite number greater than zero")
            return
        try:
            existed = self.store.put(key, body["value"], ttl)
        except (OSError, TypeError, ValueError) as exc:
            print(f"persistence error: {exc}", file=sys.stderr, flush=True)
            self._error(500, "persistence failure")
            return
        self._respond(200 if existed else 201, {"key": key, "value": body["value"]})

    def do_DELETE(self) -> None:
        key = self._key()
        if key is None:
            self._error(404, "unknown route")
        elif self.store.delete(key):
            self._respond(204)
        else:
            self._error(404, "key not found")

    def do_POST(self) -> None: self._error(405, "method not allowed")
    def do_PATCH(self) -> None: self._error(405, "method not allowed")
    def do_HEAD(self) -> None: self._error(405, "method not allowed")
    def do_OPTIONS(self) -> None: self._error(405, "method not allowed")


def serve(host: str, port: int, data: str) -> None:
    Handler.store = KVStore(data)
    server = ThreadingHTTPServer((host, port), Handler)
    server.daemon_threads = True
    print(f"LISTENING {server.server_port}", flush=True)
    previous = signal.getsignal(signal.SIGTERM)
    def stop(_signum: int, _frame: object) -> None:
        threading.Thread(target=server.shutdown, daemon=True).start()
    signal.signal(signal.SIGTERM, stop)
    try:
        server.serve_forever()
    finally:
        signal.signal(signal.SIGTERM, previous)
        server.server_close()


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--host", required=True)
    parser.add_argument("--port", required=True, type=int)
    parser.add_argument("--data", required=True)
    args = parser.parse_args()
    serve(args.host, args.port, args.data)


if __name__ == "__main__":
    main()

